import React, { useState, useRef, useEffect, useCallback } from 'react';
import { audioService } from './services/audioService';

/**
 * Minimalist Scriptum
 * A high-end minimal typing tool mimicking the provided aesthetic.
 */

const App: React.FC = () => {
  const [docName, setDocName] = useState('Untitled Document');
  const [text, setText] = useState('');
  const [dateStr] = useState(new Date().toLocaleDateString('en-GB').replace(/\//g, ','));
  const [pageNumber] = useState('p01');
  const [showCopied, setShowCopied] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Focus capture
  useEffect(() => {
    const handleGlobalClick = () => textareaRef.current?.focus();
    window.addEventListener('click', handleGlobalClick);
    textareaRef.current?.focus();
    return () => window.removeEventListener('click', handleGlobalClick);
  }, []);

  const handleTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newText = e.target.value;

    // Determine sound
    if (newText.length > text.length) {
      const char = newText[newText.length - 1];
      if (char === ' ') {
        audioService.playSpaceSound();
      } else {
        audioService.playKeySound();
      }
    } else if (newText.length < text.length) {
      audioService.playKeySound(); // Backspace sound
    }

    setText(newText);
  };

  const handleCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(text);
      setShowCopied(true);
      setTimeout(() => setShowCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  }, [text]);

  const handleSave = useCallback(() => {
    const blob = new Blob([text], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${docName.replace(/\s+/g, '_').toLowerCase()}.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  }, [text, docName]);

  return (
    <div className="min-h-screen w-full flex flex-col p-8 md:p-16 lg:p-24 selection:bg-black selection:text-[#efeae1]">
      {/* Hidden input for capturing keys */}
      <textarea
        ref={textareaRef}
        value={text}
        onChange={handleTextChange}
        className="input-capture"
        autoFocus
        spellCheck={false}
      />

      {/* Header Metadata */}
      <header className="flex flex-col md:flex-row justify-between items-baseline mb-24 gap-4">
        <div className="text-3xl md:text-4xl italic font-medium">
          <input
            type="text"
            value={docName}
            onChange={(e) => setDocName(e.target.value)}
            className="bg-transparent border-none outline-none focus:ring-0 w-full placeholder:opacity-30"
            placeholder="Document Name"
          />
        </div>
        <div className="flex gap-8 text-sm md:text-base font-inter tracking-widest opacity-60 uppercase">
          <span>{dateStr}</span>
          <span>{pageNumber}</span>
        </div>
      </header>

      {/* Main Text Area */}
      <main 
        ref={containerRef}
        className="flex-grow text-4xl md:text-5xl lg:text-6xl leading-[1.3] md:leading-[1.4] text-[#2d2d2d] font-light break-words relative cursor-text"
        onClick={() => textareaRef.current?.focus()}
      >
        {text.split('').map((char, i) => (
          <span 
            key={`${i}-${char}`} 
            className={i === text.length - 1 ? 'char-fade' : ''}
          >
            {char === '\n' ? <br /> : char}
          </span>
        ))}
        <span className="cursor-blink ml-1 border-b-2 border-[#2d2d2d] inline-block w-4 h-1 mb-1"></span>

        {text === '' && (
          <span className="absolute left-0 top-0 opacity-10 pointer-events-none select-none italic">
            Start typing your thoughts...
          </span>
        )}
      </main>

      {/* Subtle Controls */}
      <footer className="fixed bottom-8 left-8 right-8 flex justify-between items-center opacity-40 hover:opacity-100 transition-opacity duration-300">
        <div className="text-xs uppercase tracking-widest font-inter">
          {text.length} characters / {text.trim() === '' ? 0 : text.trim().split(/\s+/).length} words
        </div>

        <div className="flex gap-6 items-center">
          <button 
            onClick={handleCopy}
            className="group relative flex items-center gap-2 hover:text-black transition-colors"
            title="Copy to clipboard"
          >
            <span className="text-xs font-inter uppercase tracking-widest">
              {showCopied ? 'Copied' : 'Copy'}
            </span>
            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" className="opacity-60 group-hover:opacity-100">
              <rect width="14" height="14" x="8" y="8" rx="2" ry="2"/>
              <path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2"/>
            </svg>
          </button>

          <button 
            onClick={handleSave}
            className="group flex items-center gap-2 hover:text-black transition-colors"
            title="Download as .txt"
          >
            <span className="text-xs font-inter uppercase tracking-widest">Save</span>
            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" className="opacity-60 group-hover:opacity-100">
              <path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/>
              <polyline points="17 21 17 13 7 13 7 21"/>
              <polyline points="7 3 7 8 15 8"/>
            </svg>
          </button>
        </div>
      </footer>
    </div>
  );
};

export default App;

class AudioService {
  private audioContext: AudioContext | null = null;

  private init() {
    if (!this.audioContext) {
      this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
  }

  private createNoiseBuffer() {
    if (!this.audioContext) return null;
    const bufferSize = this.audioContext.sampleRate * 0.1; // 100ms of noise
    const buffer = this.audioContext.createBuffer(1, bufferSize, this.audioContext.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = Math.random() * 2 - 1;
    }
    return buffer;
  }

  public playKeySound() {
    this.init();
    if (!this.audioContext) return;

    if (this.audioContext.state === 'suspended') {
      this.audioContext.resume();
    }

    const now = this.audioContext.currentTime;

    // 1. Percussive Thump (The "Thud")
    const osc = this.audioContext.createOscillator();
    const gain = this.audioContext.createGain();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(120, now);
    osc.frequency.exponentialRampToValueAtTime(40, now + 0.05);
    gain.gain.setValueAtTime(0.3, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.08);
    osc.connect(gain);
    gain.connect(this.audioContext.destination);
    osc.start(now);
    osc.stop(now + 0.08);

    // 2. The "Click" (High frequency transient)
    const clickOsc = this.audioContext.createOscillator();
    const clickGain = this.audioContext.createGain();
    clickOsc.type = 'sine';
    clickOsc.frequency.setValueAtTime(1800, now);
    clickOsc.frequency.exponentialRampToValueAtTime(800, now + 0.01);
    clickGain.gain.setValueAtTime(0.1, now);
    clickGain.gain.exponentialRampToValueAtTime(0.001, now + 0.02);
    clickOsc.connect(clickGain);
    clickGain.connect(this.audioContext.destination);
    clickOsc.start(now);
    clickOsc.stop(now + 0.02);

    // 3. The "Mechanical Noise" (White noise burst)
    const noiseBuffer = this.createNoiseBuffer();
    if (noiseBuffer) {
      const noiseSource = this.audioContext.createBufferSource();
      const noiseGain = this.audioContext.createGain();
      noiseSource.buffer = noiseBuffer;
      noiseGain.gain.setValueAtTime(0.08, now);
      noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.04);
      noiseSource.connect(noiseGain);
      noiseGain.connect(this.audioContext.destination);
      noiseSource.start(now);
    }
  }

  public playSpaceSound() {
    this.init();
    if (!this.audioContext) return;

    const now = this.audioContext.currentTime;

    // Space bar is usually a deeper, wider sound
    const osc = this.audioContext.createOscillator();
    const gain = this.audioContext.createGain();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(80, now);
    osc.frequency.exponentialRampToValueAtTime(30, now + 0.12);
    gain.gain.setValueAtTime(0.4, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.15);
    osc.connect(gain);
    gain.connect(this.audioContext.destination);
    osc.start(now);
    osc.stop(now + 0.15);

    const noiseBuffer = this.createNoiseBuffer();
    if (noiseBuffer) {
      const noiseSource = this.audioContext.createBufferSource();
      const noiseGain = this.audioContext.createGain();
      noiseSource.buffer = noiseBuffer;
      noiseGain.gain.setValueAtTime(0.05, now);
      noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.08);
      noiseSource.connect(noiseGain);
      noiseGain.connect(this.audioContext.destination);
      noiseSource.start(now);
    }
  }
}

