class AudioService {
  private audioContext: AudioContext | null = null;

  private init() {
    if (!this.audioContext) {
      this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
  }

  private createNoiseBuffer() {
    if (!this.audioContext) return null;
    const bufferSize = this.audioContext.sampleRate * 0.15; // 150ms of noise
    const buffer = this.audioContext.createBuffer(1, bufferSize, this.audioContext.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = Math.random() * 2 - 1;
    }
    return buffer;
  }

  public playKeySound() {
    this.init();
    if (!this.audioContext) return;

    if (this.audioContext.state === 'suspended') {
      this.audioContext.resume();
    }

    const now = this.audioContext.currentTime;

    // 1. Percussive Body (The "Thump" of the key bottoming out)
    const bodyOsc = this.audioContext.createOscillator();
    const bodyGain = this.audioContext.createGain();
    bodyOsc.type = 'triangle';
    bodyOsc.frequency.setValueAtTime(160, now);
    bodyOsc.frequency.exponentialRampToValueAtTime(60, now + 0.08);
    bodyGain.gain.setValueAtTime(0.5, now);
    bodyGain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
    bodyOsc.connect(bodyGain);
    bodyGain.connect(this.audioContext.destination);
    bodyOsc.start(now);
    bodyOsc.stop(now + 0.12);

    // 2. High Transient Clack (The metal-on-paper/metal-on-metal hit)
    const clickOsc = this.audioContext.createOscillator();
    const clickGain = this.audioContext.createGain();
    clickOsc.type = 'sine';
    clickOsc.frequency.setValueAtTime(2400, now);
    clickOsc.frequency.exponentialRampToValueAtTime(1200, now + 0.02);
    clickGain.gain.setValueAtTime(0.2, now);
    clickGain.gain.exponentialRampToValueAtTime(0.001, now + 0.03);
    clickOsc.connect(clickGain);
    clickGain.connect(this.audioContext.destination);
    clickOsc.start(now);
    clickOsc.stop(now + 0.03);

    // 3. Mechanical Crunch (White noise burst filtered for crispness)
    const noiseBuffer = this.createNoiseBuffer();
    if (noiseBuffer) {
      const noiseSource = this.audioContext.createBufferSource();
      const noiseGain = this.audioContext.createGain();
      const filter = this.audioContext.createBiquadFilter();

      noiseSource.buffer = noiseBuffer;
      filter.type = 'highpass';
      filter.frequency.setValueAtTime(1500, now);

      noiseGain.gain.setValueAtTime(0.12, now);
      noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.06);

      noiseSource.connect(filter);
      filter.connect(noiseGain);
      noiseGain.connect(this.audioContext.destination);
      noiseSource.start(now);
    }
  }

  public playSpaceSound() {
    this.init();
    if (!this.audioContext) return;

    const now = this.audioContext.currentTime;

    // Space bar: deeper, hollower "thunk"
    const osc = this.audioContext.createOscillator();
    const gain = this.audioContext.createGain();
    osc.type = 'triangle';
    osc.frequency.setValueAtTime(100, now);
    osc.frequency.exponentialRampToValueAtTime(40, now + 0.15);
    gain.gain.setValueAtTime(0.6, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.2);
    osc.connect(gain);
    gain.connect(this.audioContext.destination);
    osc.start(now);
    osc.stop(now + 0.2);

    const noiseBuffer = this.createNoiseBuffer();
    if (noiseBuffer) {
      const noiseSource = this.audioContext.createBufferSource();
      const noiseGain = this.audioContext.createGain();
      const filter = this.audioContext.createBiquadFilter();

      noiseSource.buffer = noiseBuffer;
      filter.type = 'lowpass';
      filter.frequency.setValueAtTime(2000, now);

      noiseGain.gain.setValueAtTime(0.08, now);
      noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);

      noiseSource.connect(filter);
      filter.connect(noiseGain);
      noiseGain.connect(this.audioContext.destination);
      noiseSource.start(now);
    }
  }
}

