class AudioService {
  private audioContext: AudioContext | null = null;

  private init() {
    if (!this.audioContext) {
      this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
  }

  private createNoiseBuffer() {
    if (!this.audioContext) return null;
    const bufferSize = this.audioContext.sampleRate * 0.2; // 200ms of noise
    const buffer = this.audioContext.createBuffer(1, bufferSize, this.audioContext.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = Math.random() * 2 - 1;
    }
    return buffer;
  }

  /**
   * Generates a mechanical keystroke sound.
   * Layers: 
   * 1. Transient Click (Metal on Metal)
   * 2. Body Thud (Keycap meeting board)
   * 3. Mechanical Friction (Noise)
   */
  public playKeySound(isSpace = false) {
    this.init();
    if (!this.audioContext) return;

    if (this.audioContext.state === 'suspended') {
      this.audioContext.resume();
    }

    const now = this.audioContext.currentTime;

    // Add slight randomization to pitch and timing to mimic human typing
    const pitchShift = (Math.random() - 0.5) * 0.1; 
    const gainVar = (Math.random() * 0.1) + 0.9;

    // 1. THE "THUD" (Body resonance)
    const bodyOsc = this.audioContext.createOscillator();
    const bodyGain = this.audioContext.createGain();
    bodyOsc.type = 'triangle';
    // Space is deeper and more hollow
    const baseFreq = isSpace ? 80 : 160;
    bodyOsc.frequency.setValueAtTime(baseFreq * (1 + pitchShift), now);
    bodyOsc.frequency.exponentialRampToValueAtTime(30, now + (isSpace ? 0.15 : 0.08));

    bodyGain.gain.setValueAtTime(0.4 * gainVar, now);
    bodyGain.gain.exponentialRampToValueAtTime(0.001, now + (isSpace ? 0.18 : 0.12));

    bodyOsc.connect(bodyGain);
    bodyGain.connect(this.audioContext.destination);
    bodyOsc.start(now);
    bodyOsc.stop(now + 0.2);

    // 2. THE "CLACK" (Initial metal transient)
    const clickOsc = this.audioContext.createOscillator();
    const clickGain = this.audioContext.createGain();
    clickOsc.type = 'sine';
    clickOsc.frequency.setValueAtTime(isSpace ? 1500 : 2800 * (1 + pitchShift), now);
    clickOsc.frequency.exponentialRampToValueAtTime(800, now + 0.015);

    clickGain.gain.setValueAtTime(isSpace ? 0.08 : 0.15 * gainVar, now);
    clickGain.gain.exponentialRampToValueAtTime(0.001, now + 0.03);

    clickOsc.connect(clickGain);
    clickGain.connect(this.audioContext.destination);
    clickOsc.start(now);
    clickOsc.stop(now + 0.05);

    // 3. THE "CRUNCH" (Mechanical clatter / white noise)
    const noiseBuffer = this.createNoiseBuffer();
    if (noiseBuffer) {
      const noiseSource = this.audioContext.createBufferSource();
      const noiseGain = this.audioContext.createGain();
      const filter = this.audioContext.createBiquadFilter();

      noiseSource.buffer = noiseBuffer;
      filter.type = isSpace ? 'bandpass' : 'highpass';
      filter.frequency.setValueAtTime(isSpace ? 800 : 2200, now);
      filter.Q.value = 1.5;

      noiseGain.gain.setValueAtTime(isSpace ? 0.12 : 0.18 * gainVar, now);
      noiseGain.gain.exponentialRampToValueAtTime(0.001, now + (isSpace ? 0.12 : 0.07));

      noiseSource.connect(filter);
      filter.connect(noiseGain);
      noiseGain.connect(this.audioContext.destination);
      noiseSource.start(now);
    }
  }

  public playSpaceSound() {
    this.playKeySound(true);
  }
}

