class AudioService {
  private audioContext: AudioContext | null = null;
  private externalBuffer: AudioBuffer | null = null;

  private init() {
    if (!this.audioContext) {
      this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
  }

  /**
   * Allows the user to load an external sound from a URL.
   */
  public async loadExternalSound(url: string) {
    this.init();
    if (!this.audioContext) return;
    try {
      const response = await fetch(url);
      const arrayBuffer = await response.arrayBuffer();
      this.externalBuffer = await this.audioContext.decodeAudioData(arrayBuffer);
    } catch (e) {
      console.error("Failed to load external sound:", e);
    }
  }

  private createNoiseBuffer(duration = 0.2) {
    if (!this.audioContext) return null;
    const bufferSize = this.audioContext.sampleRate * duration;
    const buffer = this.audioContext.createBuffer(1, bufferSize, this.audioContext.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = Math.random() * 2 - 1;
    }
    return buffer;
  }

  /**
   * Advanced Mechanical Keyboard Synthesis
   */
  public playKeySound(isSpace = false) {
    this.init();
    if (!this.audioContext) return;

    if (this.audioContext.state === 'suspended') {
      this.audioContext.resume();
    }

    // Play external sound if loaded
    if (this.externalBuffer) {
      const source = this.audioContext.createBufferSource();
      source.buffer = this.externalBuffer;
      source.connect(this.audioContext.destination);
      source.start(0);
      return;
    }

    const now = this.audioContext.currentTime;
    const pitchShift = (Math.random() - 0.5) * 0.15; 
    const gainVar = (Math.random() * 0.2) + 0.9;

    // 1. THE "THOCK" (Low frequency case resonance)
    const thockOsc = this.audioContext.createOscillator();
    const thockGain = this.audioContext.createGain();
    thockOsc.type = 'sine';
    const baseFreq = isSpace ? 75 : 145;
    thockOsc.frequency.setValueAtTime(baseFreq * (1 + pitchShift), now);
    thockOsc.frequency.exponentialRampToValueAtTime(20, now + (isSpace ? 0.2 : 0.1));
    thockGain.gain.setValueAtTime(isSpace ? 0.7 : 0.5 * gainVar, now);
    thockGain.gain.exponentialRampToValueAtTime(0.001, now + (isSpace ? 0.25 : 0.15));
    thockOsc.connect(thockGain);
    thockGain.connect(this.audioContext.destination);
    thockOsc.start(now);
    thockOsc.stop(now + 0.3);

    // 2. THE "CLACK" (Sharp transient of the switch)
    const clackOsc = this.audioContext.createOscillator();
    const clackGain = this.audioContext.createGain();
    clackOsc.type = 'square'; // Richer harmonics for a metallic feel
    clackOsc.frequency.setValueAtTime(isSpace ? 1200 : 3200 * (1 + pitchShift), now);
    clackOsc.frequency.exponentialRampToValueAtTime(400, now + 0.02);
    clackGain.gain.setValueAtTime(isSpace ? 0.05 : 0.12 * gainVar, now);
    clackGain.gain.exponentialRampToValueAtTime(0.001, now + 0.04);
    clackOsc.connect(clackGain);
    clackGain.connect(this.audioContext.destination);
    clackOsc.start(now);
    clackOsc.stop(now + 0.05);

    // 3. SPRING PING (High frequency metallic resonance)
    const pingOsc = this.audioContext.createOscillator();
    const pingGain = this.audioContext.createGain();
    pingOsc.type = 'sine';
    pingOsc.frequency.setValueAtTime(5000 + (Math.random() * 1000), now);
    pingGain.gain.setValueAtTime(0.02 * gainVar, now);
    pingGain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
    pingOsc.connect(pingGain);
    pingGain.connect(this.audioContext.destination);
    pingOsc.start(now);
    pingOsc.stop(now + 0.15);

    // 4. MECHANICAL RATTLE (Filtered noise)
    const noiseBuffer = this.createNoiseBuffer(0.1);
    if (noiseBuffer) {
      const noiseSource = this.audioContext.createBufferSource();
      const noiseGain = this.audioContext.createGain();
      const filter = this.audioContext.createBiquadFilter();
      noiseSource.buffer = noiseBuffer;
      filter.type = 'highpass';
      filter.frequency.setValueAtTime(isSpace ? 1000 : 2500, now);
      noiseGain.gain.setValueAtTime(isSpace ? 0.1 : 0.15 * gainVar, now);
      noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.08);
      noiseSource.connect(filter);
      filter.connect(noiseGain);
      noiseGain.connect(this.audioContext.destination);
      noiseSource.start(now);
    }
  }

  public playSpaceSound() {
    this.playKeySound(true);
  }
}

