class AudioService {
  private audioContext: AudioContext | null = null;

  private init() {
    if (!this.audioContext) {
      this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
  }

  /**
   * Synthesizes a sound mimicking the iOS keyboard "tock".
   * It consists of a low-end "thud", a high-end "tick" and a tiny bit of noise for texture.
   */
  public playKeySound(isSpace = false) {
    this.init();
    if (!this.audioContext) return;

    if (this.audioContext.state === 'suspended') {
      this.audioContext.resume();
    }

    const now = this.audioContext.currentTime;

    // 1. The "Thud" (Body of the click)
    const bodyOsc = this.audioContext.createOscillator();
    const bodyGain = this.audioContext.createGain();
    bodyOsc.type = 'sine';
    // Space is slightly deeper
    bodyOsc.frequency.setValueAtTime(isSpace ? 140 : 180, now);
    bodyGain.gain.setValueAtTime(0.15, now);
    bodyGain.gain.exponentialRampToValueAtTime(0.001, now + 0.03);
    bodyOsc.connect(bodyGain);
    bodyGain.connect(this.audioContext.destination);
    bodyOsc.start(now);
    bodyOsc.stop(now + 0.04);

    // 2. The "Tick" (High frequency transient)
    const tickOsc = this.audioContext.createOscillator();
    const tickGain = this.audioContext.createGain();
    tickOsc.type = 'sine';
    tickOsc.frequency.setValueAtTime(isSpace ? 1100 : 1400, now);
    tickGain.gain.setValueAtTime(0.08, now);
    tickGain.gain.exponentialRampToValueAtTime(0.001, now + 0.015);
    tickOsc.connect(tickGain);
    tickGain.connect(this.audioContext.destination);
    tickOsc.start(now);
    tickOsc.stop(now + 0.02);

    // 3. Texture (Filtered noise for a more organic feel)
    const bufferSize = this.audioContext.sampleRate * 0.02;
    const noiseBuffer = this.audioContext.createBuffer(1, bufferSize, this.audioContext.sampleRate);
    const data = noiseBuffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = Math.random() * 2 - 1;
    }
    const noiseSource = this.audioContext.createBufferSource();
    noiseSource.buffer = noiseBuffer;
    const noiseFilter = this.audioContext.createBiquadFilter();
    noiseFilter.type = 'bandpass';
    noiseFilter.frequency.setValueAtTime(2000, now);
    const noiseGain = this.audioContext.createGain();
    noiseGain.gain.setValueAtTime(0.03, now);
    noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.02);

    noiseSource.connect(noiseFilter);
    noiseFilter.connect(noiseGain);
    noiseGain.connect(this.audioContext.destination);
    noiseSource.start(now);
  }

  public playSpaceSound() {
    this.playKeySound(true);
  }
}

