class AudioService {
  private audioContext: AudioContext | null = null;

  private init() {
    if (!this.audioContext) {
      this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
  }

  /**
   * Synthesizes the acoustic signature of SKCM Blue Alps switches.
   * Characteristics: Sharp metallic click-leaf sound + Deep TKL case resonance + Spring ping.
   */
  public playKeySound(isSpace = false) {
    this.init();
    if (!this.audioContext) return;

    if (this.audioContext.state === 'suspended') {
      this.audioContext.resume();
    }

    const now = this.audioContext.currentTime;
    // Add organic variation
    const pitchShift = (Math.random() - 0.5) * 0.1;
    const gainVar = 0.8 + Math.random() * 0.4;

    // 1. THE "CLICK LEAF" (Metallic high-pitched click)
    // Blue Alps are famous for this crisp, clean click.
    const clickOsc = this.audioContext.createOscillator();
    const clickGain = this.audioContext.createGain();
    clickOsc.type = 'triangle'; // Complex enough to sound metallic
    clickOsc.frequency.setValueAtTime((isSpace ? 2200 : 3200) * (1 + pitchShift), now);
    clickOsc.frequency.exponentialRampToValueAtTime(1000, now + 0.01);
    clickGain.gain.setValueAtTime(0.12 * gainVar, now);
    clickGain.gain.exponentialRampToValueAtTime(0.001, now + 0.02);
    clickOsc.connect(clickGain);
    clickGain.connect(this.audioContext.destination);
    clickOsc.start(now);
    clickOsc.stop(now + 0.03);

    // 2. THE "THUD" (Case resonance / Bottom out)
    // Simulating the hollow TKL plastic case.
    const thudOsc = this.audioContext.createOscillator();
    const thudGain = this.audioContext.createGain();
    thudOsc.type = 'sine';
    const baseFreq = isSpace ? 90 : 160;
    thudOsc.frequency.setValueAtTime(baseFreq * (1 + pitchShift), now);
    thudOsc.frequency.exponentialRampToValueAtTime(40, now + 0.08);
    thudGain.gain.setValueAtTime(isSpace ? 0.4 : 0.25 * gainVar, now);
    thudGain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
    thudOsc.connect(thudGain);
    thudGain.connect(this.audioContext.destination);
    thudOsc.start(now);
    thudOsc.stop(now + 0.15);

    // 3. SPRING PING (High-end metallic ring)
    const pingOsc = this.audioContext.createOscillator();
    const pingGain = this.audioContext.createGain();
    pingOsc.type = 'sine';
    pingOsc.frequency.setValueAtTime(5000 + (Math.random() * 500), now);
    pingGain.gain.setValueAtTime(0.02 * gainVar, now);
    pingGain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
    pingOsc.connect(pingGain);
    pingGain.connect(this.audioContext.destination);
    pingOsc.start(now);
    pingOsc.stop(now + 0.12);

    // 4. KEYCAP TEXTURE (White noise)
    const bufferSize = this.audioContext.sampleRate * 0.05;
    const noiseBuffer = this.audioContext.createBuffer(1, bufferSize, this.audioContext.sampleRate);
    const data = noiseBuffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = Math.random() * 2 - 1;
    }
    const noiseSource = this.audioContext.createBufferSource();
    noiseSource.buffer = noiseBuffer;
    const noiseFilter = this.audioContext.createBiquadFilter();
    noiseFilter.type = 'highpass';
    noiseFilter.frequency.setValueAtTime(isSpace ? 1500 : 2500, now);
    const noiseGain = this.audioContext.createGain();
    noiseGain.gain.setValueAtTime(0.05 * gainVar, now);
    noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.04);

    noiseSource.connect(noiseFilter);
    noiseFilter.connect(noiseGain);
    noiseGain.connect(this.audioContext.destination);
    noiseSource.start(now);
  }

  public playSpaceSound() {
    this.playKeySound(true);
  }
}

